window.AUTH=window.AUTH||{};window.AUTH["25-112"]={"d":"25-112","id":"2025/25-112","n":"Chatrie v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Okello Chatrie","date":"2026-02-23","url":"https://www.supremecourt.gov/DocketPDF/25/25-112/397074/20260223160717593_25-112%20-%20Opening%20Brief.pdf","side":"pet","n":52},{"k":"respondent","label":"Brief of respondent United States","date":"2026-03-25","url":"https://www.supremecourt.gov/DocketPDF/25/25-112/401871/20260325184404433_25-112bsUnitedStates.pdf","side":"res","n":45},{"k":"reply","label":"Reply of petitioner Okello Chatrie","date":"2026-04-17","url":"https://www.supremecourt.gov/DocketPDF/25/25-112/404764/20260417152749041_Reply%20Brief%20for%20Petitioner%20PDFA.pdf","side":"pet","n":24}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us2r64_7mio.pdf","tr":true,"items":[{"t":"case","label":"Agency for Health Care Administration v. Associated Industries of Florida, Inc.","cite":"678 So. 2d 1239","y":1996,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/678/1239/","by":{"0":"17-18"}},{"t":"case","label":"Arizona v. Hicks","cite":"480 U.S. 321","y":1987,"id":"1986/85-1027","sc":1,"by":{"0":"35, 52","1":"44"},"q":[{"src":"brief","b":0,"text":"thermal-imaging device aimed at a private home from a public street to detect relative amounts of heat within the home","cite":"480 U.S. 321"}]},{"t":"case","label":"Berger v. New York","cite":"388 U.S. 41","y":1967,"id":"1966/615","sc":1,"by":{"0":"40"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"Why isn't this closer to the warrants that we permitted with beepers, where we don't have a person or necessarily a place in mind, but we have a location and general things, why isn't that more consonant with Berger, Zucker, Karo, those lines of cases?"}]},{"t":"case","label":"Bond v. United States","cite":"529 U.S. 334","y":2000,"id":"1999/98-9349","sc":1,"by":{"0":"44"}},{"t":"case","label":"Buchanan v. Warley","cite":"245 U.S. 60","y":1917,"id":"1900-1940/245us60","sc":1,"by":{"0":"15"},"q":[{"src":"brief","b":0,"text":"Property consists of the free use, enjoyment, and disposal of a person’s acquisitions without control or diminution save by the law of the land.","cite":"245 U.S. 60, 74"}]},{"t":"case","label":"Budsgunshop.com, LLC v. Security Safe Outlet, Inc.","cite":"2012 WL 1899851","y":2012,"court":"E.D. Ky. May 23","by":{"0":"17"}},{"t":"case","label":"Carpenter v. United States","cite":"585 U.S. 296","y":2018,"id":"2017/16-402","sc":1,"by":{"0":"11, 14, 19-26, 28, 32, 42","1":"3, 11, 13, 16-18, 20, 22, 23","2":"5, 7, 8, 10, 15, 19"},"q":[{"src":"brief","b":0,"text":"[a] bailee who uses the item in a different way than he’s supposed to, or against the bailor’s instructions, is liable for conversion.","cite":"585 U.S. at 399"},{"src":"brief","b":0,"text":"easy, cheap, and efficient compared to traditional investigative tools.","cite":"585 U.S. at 311"},{"src":"brief","b":1,"text":"an ‘all-encompassing record of [petitioner’s] whereabouts.’","cite":"585 U.S. 296, 311"},{"src":"brief","b":1,"text":"familial, political, professional, religious, and sexual associations,","cite":"585 U.S. at 311"},{"src":"brief","b":2,"text":"do not involve the direct taking of evidence.","cite":"585 U.S. at 317"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"to safeguard the privacy and security of individuals against arbitrary invasions by governmental offcials.","cite":"585 U. S. 296, 303"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"individuals have a reasonable expectation of privacy in the whole of their physical movements.","cite":"585 U. S., at 310"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"society's expectation has been that law enforcement agents and others would not—and indeed, in the main, simply could not—secretly monitor and catalogue every single movement 6 An overlapping set of fve Justices decided the case on a different ground, based on the Government's physical trespass of the vehicle. See Jones, 565 U. S., at 404–405. of an individual's car.","cite":"585 U. S., at 310"},{"src":"argument","who":"Mr. Unikowsky","text":"I mean, in Carpenter, the cart -- Court relied on reasonable expectations of privacy. We think there's two different sources here of the reasonable expectation."},{"src":"argument","who":"Justice Barrett","text":"Well, this is pretty -- so I think Carpenter -- we haven't talked about Carpenter yet -- is -- is pretty on point, but this is different from Carpenter."},{"src":"argument","who":"Mr. Unikowsky","text":"So I still think that even though the stretch of time was lower than in Carpenter, there is still a reasonable expectation of privacy for a few reasons."}]},{"t":"case","label":"Cedar Point Nursery v. Hassid","cite":"594 U.S. 139","y":2021,"id":"2020/20-107","sc":1,"by":{"0":"15"},"q":[{"src":"brief","b":0,"text":"one of the most treasured rights of property ownership.","cite":"594 U.S. 139, 149"}]},{"t":"case","label":"Chapman v. United States","cite":"365 U.S. 610","y":1961,"id":"1960/175","sc":1,"by":{"0":"20"}},{"t":"case","label":"Entick v. Carrington","cite":"19 How. St. Tr. 1029","y":1765,"court":"C.P.","url":"https://www.courtlistener.com/c/How.%20St.%20Tr./19/1029/","by":{"0":"20, 34, 37","1":"33","2":"5"}},{"t":"case","label":"Gerstein v. Pugh","cite":"420 U.S. 103","y":1975,"id":"1973/73-477","sc":1,"by":{"0":"47"}},{"t":"case","label":"Groh v. Ramirez","cite":"540 U.S. 551","y":2004,"id":"2003/02-811","sc":1,"by":{"0":"32"},"q":[{"src":"brief","b":0,"text":"[T]he presumptive rule against warrantless searches applies with equal force to searches whose only defect is a lack of particularity in the warrant.","cite":"540 U.S. 551, 559"}]},{"t":"case","label":"Ground Zero Museum Workshop v. Wilson","cite":"813 F. Supp. 2d 678","y":2011,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/813/678/","by":{"0":"17"}},{"t":"case","label":"Illinois v. Gates","cite":"462 U.S. 213","y":1983,"id":"1982/81-430","sc":1,"by":{"0":"37, 47, 50","1":"38, 39"},"q":[{"src":"brief","b":0,"text":"evidence of a crime will be found in a particular place.","cite":"462 U.S. at 238"},{"src":"brief","b":1,"text":"fair probability that contraband or evidence of crime will be found in a particular place.","cite":"462 U.S. 213, 238"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"[P]robable cause is a fuid concept— turning on the assessment of probabilities in particular factual contexts—not readily, or even usefully, reduced to a neat set of legal rules.","cite":"462 U. S. 213, 232"}]},{"t":"case","label":"Integrated Direct Marketing, LLC v. May","cite":"495 S.W.3d 73","y":2016,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/495/73/","by":{"0":"17"}},{"t":"case","label":"Johnson v. United States","cite":"333 U.S. 10","y":1948,"id":"scdb/1947-031","sc":1,"by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"by a neutral and detached magistrate instead of … by the officer engaged in the often competitive enterprise of ferreting out crime.","cite":"333 U.S. 10, 13-14"}]},{"t":"case","label":"Katz v. United States","cite":"389 U.S. 347","y":1967,"id":"1967/35","sc":1,"by":{"0":"14","1":"30-31"},"q":[{"src":"argument","who":"Justice Barrett","text":"One way to think about this case is that, listen, our physical intrusion cases, our property cases require a physical intrusion, and Katz set us off on this course that when we're talking about technology, we think about it in terms of reasonable expectations of privacy."},{"src":"argument","who":"Mr. Feigin","text":"I think the Court has made clear in Knotts that exposing your public location for two hours, you don't have a privacy expectation in that, and that contrasts sharply with cases like Ex Parte Jackson about physical letters or even a case like Katz, which is about telephonic --"}]},{"t":"case","label":"Kremen v. Cohen","cite":"337 F.3d 1024","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/337/1024/","by":{"0":"17"}},{"t":"case","label":"Kyllo v. United States","cite":"533 U.S. 27","y":2001,"id":"2000/99-8508","sc":1,"by":{"0":"35, 43, 45","1":"24, 31","2":"5, 9"},"q":[{"src":"brief","b":1,"text":"a device that is not in general public use, to explore details of the home that would previously have been unknowable without physical intrusion,","cite":"533 U.S. 27, 40"},{"src":"argument","who":"Mr. Unikowsky","text":"Even if a tool is used, like, you know, the Kyllo tool, you know, the Thermovision, for any reason, if I have stuff inside, people won't look at it in order to conduct a law enforcement investigation."}]},{"t":"case","label":"Leach v. Three of the King’s Messengers","cite":"19 How. St. Tr. 1001","y":1765,"url":"https://www.courtlistener.com/c/How.%20St.%20Tr./19/1001/","by":{"0":"47"}},{"t":"case","label":"Maryland v. Garrison","cite":"480 U.S. 79","y":1987,"id":"1986/85-759","sc":1,"by":{"0":"38"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"carefully tailored to its justifcations, and will not take on the character of the wide-ranging exploratory searches the Framers intended to prohibit.","cite":"480 U. S. 79, 84"}]},{"t":"case","label":"McDonald v. Kiloo ApS","cite":"385 F. Supp. 3d 1022","y":2019,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/385/1022/","by":{"0":"17"}},{"t":"case","label":"Microsoft Corp. v. John Does 1-8","cite":"2015 WL 4937441","y":2015,"court":"E.D. Va. Aug. 17","by":{"0":"17"}},{"t":"case","label":"New Mexico ex rel. Balderas v. Tiny Lab Productions","cite":"457 F. Supp. 3d 1103","y":2020,"court":"D.N.M.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/457/1103/","by":{"0":"17"}},{"t":"case","label":"Physicians Interactive v. Lathian Systems, Inc.","cite":"2003 WL 23018270","y":2003,"court":"E.D. Va. Dec. 5","by":{"0":"16"}},{"t":"case","label":"Riley v. California","cite":"573 U.S. 373","y":2014,"id":"2013/13-132","sc":1,"by":{"0":"19","1":"3, 41","2":"4, 19"},"q":[{"src":"brief","b":0,"text":"was the founding generation’s response to the reviled ‘general warrants’ and ‘writs of assistance’ of the colonial era, which allowed British officers to rummage through homes in an unrestrained search for evidence of criminal activity.","cite":"573 U.S. at 403"},{"src":"brief","b":1,"text":"the reviled ‘general warrants’ and ‘writs of assistance’ of the colonial era, which allowed British officers to rummage through homes in an unrestrained search for evidence of criminal activity,","cite":"573 U.S. 373, 403"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"such a pervasive and insistent part of daily life that the proverbial visitor from Mars might conclude they were an important feature of human anatomy.","cite":"573 U. S. 373, 385"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"detailed information about all aspects of a person's life.","cite":"573 U. S., at 396"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"the capacity of Internet-connected devices to display data stored on remote servers rather than on the device itself.","cite":"573 U. S., at 397"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"keep defendants and judges guessing for years to come.","cite":"573 U. S. 373, 401"},{"src":"argument","who":"Mr. Feigin","text":"One, in Carpenter, you had essentially the creation of CSLI, you know, Cell Site Location Information, as the price of even having a cell phone, which the Court had said in Riley was a device that basically nobody can live without."},{"src":"argument","who":"Mr. Feigin","text":"I think that would be much closer to Carpenter because I think, if I'm recalling correctly from Riley, it's something like 90 percent of people have cell phones."},{"src":"argument","who":"Mr. Feigin","text":"Here is a case where I think, as the Court recognized in Riley can often happen, the physical analogies kind of break down to some degree. The Court has been clear in Smith against Maryland --"}]},{"t":"case","label":"Skapinetz v. CoesterVMS.com, Inc.","cite":"2018 WL 805393","y":2018,"court":"D. Md. Feb. 9","by":{"0":"16"}},{"t":"case","label":"Skinner v. Railway Labor Executives’ Ass’n","cite":"489 U.S. 602","y":1989,"id":"1988/87-1555","sc":1,"by":{"0":"33","1":"42, 43","2":"17"},"q":[{"src":"brief","b":0,"text":"Although the Fourth Amendment does not apply to a search or seizure, even an arbitrary one, effected by a private party on his own initiative, the Amendment protects against such intrusions if the private party acted as an instrument or agent of the Government.","cite":"489 U.S. 602, 614"},{"src":"brief","b":1,"text":"necessarily 3 A design choice might make a difference if it were to render the recipient of a geofence warrant incapable of complying with it. The government’s understanding is that Google’s recent decision to eliminate a centralized database altogether, and store Location History information on mobile devices themselves, is such a change. See Br. in Opp. 18. turn[] on the degree of the Government’s participation in the private party’s activities.","cite":"489 U.S. at 614"},{"src":"brief","b":2,"text":"the lawfulness of its acts is controlled by the Fourth Amendment.","cite":"489 U.S. 602, 614-16"}]},{"t":"case","label":"Smith v. Maryland","cite":"442 U.S. 735","y":1979,"id":"1978/78-5374","sc":1,"by":{"0":"25-27","1":"2, 12, 15, 16, 18, 21, 23, 28, 42","2":"11"},"q":[{"src":"brief","b":1,"text":"a person has no legitimate expectation of privacy in information he voluntarily turns over to third parties.","cite":"442 U.S. 735, 743-744"},{"src":"brief","b":1,"text":"assume[s] the risk that the information would be divulged to police.","cite":"442 U.S. at 743"}]},{"t":"case","label":"Stanford v. Texas","cite":"379 U.S. 476","y":1965,"id":"1964/40","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"Vivid in the memory of the newly independent Americans were those general warrants known as writs of assistance under which officers of the Crown had so bedeviled the colonists.","cite":"379 U.S. 476, 481"}]},{"t":"case","label":"Steagald v. United States","cite":"451 U.S. 204","y":1981,"id":"1980/79-6777","sc":1,"by":{"0":"42, 53","2":"23"},"q":[{"src":"brief","b":0,"text":"[W]rits of assistance ... noted only the object of the search—any uncustomed goods—and thus left customs officials completely free to search any place where they believed such goods might be.","cite":"451 U.S. 204, 220"}]},{"t":"case","label":"Steele v. United States","cite":"267 U.S. 498","y":1925,"id":"scdb/1924-113","sc":1,"by":{"0":"46, 53"},"q":[{"src":"brief","b":0,"text":"the description is such that the officer with a search warrant can, with reasonable effort ascertain and identify the place intended.","cite":"267 U.S. 498, 503"}]},{"t":"case","label":"Sturm v. Boker","cite":"150 U.S. 312","y":1893,"id":"scdb/1893-042","sc":1,"by":{"0":"21"}},{"t":"case","label":"Thyroff v. Nationwide Mutual Insurance Co.","cite":"864 N.E.2d 1272","y":2007,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/864/1272/","by":{"0":"17"}},{"t":"case","label":"United States v. Di Re","cite":"332 U.S. 581","y":1948,"id":"scdb/1947-021","sc":1,"by":{"0":"36-37","2":"18"},"q":[{"src":"brief","b":0,"text":"[A] search is not to be made legal by what it turns up. In law it is good or bad when it starts and does not change character from its success.","cite":"332 U.S. 581, 595"},{"src":"brief","b":2,"text":"[A] search is not to be made legal by what it turns up.","cite":"332 U.S. 581, 595"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"to place obstacles in the way of a too permeating police surveillance.","cite":"332 U. S. 581, 595"}]},{"t":"case","label":"United States v. Grubbs","cite":"547 U.S. 90","y":2006,"id":"2005/04-1414","sc":1,"by":{"0":"48, 49","2":"21"}},{"t":"case","label":"United States v. Miller","cite":"425 U.S. 435","y":1976,"id":"1975/74-1179","sc":1,"by":{"0":"25, 27","1":"2, 16, 21, 26, 28","2":"11"},"q":[{"src":"brief","b":1,"text":"that the Fourth Amendment does not prohibit the obtaining of information revealed to a third party and conveyed by him to Government authorities, even if the information is revealed on the assumption that it will be used only for a limited purpose and the confidence placed in the third party will not be betrayed.","cite":"425 U.S. at 443"}]},{"t":"case","label":"United States v. New York Telephone Co.","cite":"434 U.S. 159","y":1977,"id":"1977/76-835","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"commanded ‘all officers and subjects of the Crown to assist in their execution.’","cite":"434 U.S. 159, 180 n.3"}]},{"t":"case","label":"United States v. United States District Court for Eastern District of Michigan","cite":"407 U.S. 297","y":1972,"id":"1971/70-153","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"It is not fit that the receiving or judging of the information should be left to the discretion of the officer. The magistrate ought to judge; and should give certain directions to the officer.","cite":"407 U.S. 297, 316"}]},{"t":"case","label":"ix United States v. Van Leeuwen","cite":"397 U.S. 249","y":1970,"id":"1969/403","sc":1,"by":{"0":"39"}},{"t":"case","label":"United States v. Warshak","cite":"631 F.3d 266","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/631/266/","by":{"0":"21-22","2":"10"}},{"t":"case","label":"Ybarra v. Illinois","cite":"444 U.S. 85","y":1979,"id":"1979/78-5937","sc":1,"by":{"0":"50","1":"44, 45","2":"22"},"q":[{"src":"brief","b":0,"text":"mere propinquity to others independently suspected of criminal activity does not, without more, give rise to probable cause to search that person.","cite":"444 U.S. 85, 91"},{"src":"brief","b":2,"text":"probable cause to search that person.","cite":"444 U.S. 85, 91"},{"src":"argument","who":"Mr. Unikowsky","text":"And so that's why I think that the Ybarra case is directly on point here. You don't have probable cause to search based on someone's proximity to the crime."}]},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"4, 37","2":"1"}},{"t":"usc","label":"18 U.S.C. § 2510","url":"https://www.law.cornell.edu/uscode/text/18/2510","subs":["(8)","(12)(C)"],"stext":{"head":"§2510. Definitions","paras":[[0,"As used in this chapter—"],[1,"(1) \"wire communication\" means any aural transfer made in whole or in part through the use of facilities for the transmission of communications by the aid of wire, cable, or other like connection between the point of origin and the point of reception (including the use of such connection in a switching station) furnished or operated by any person engaged in providing or operating such facilities for the transmission of interstate or foreign communications or communications affecting interstate or foreign commerce;"],[1,"(2) \"oral communication\" means any oral communication uttered by a person exhibiting an expectation that such communication is not subject to interception under circumstances justifying such expectation, but such term does not include any electronic communication;"],[1,"(3) \"State\" means any State of the United States, the District of Columbia, the Commonwealth of Puerto Rico, and any territory or possession of the United States;"],[1,"(4) \"intercept\" means the aural or other acquisition of the contents of any wire, electronic, or oral communication through the use of any electronic, mechanical, or other device.1"],[1,"(5) \"electronic, mechanical, or other device\" means any device or apparatus which can be used to intercept a wire, oral, or electronic communication other than—"],[2,"(a) any telephone or telegraph instrument, equipment or facility, or any component thereof, (i) furnished to the subscriber or user by a provider of wire or electronic communication service in the ordinary course of its business and being used by the subscriber or user in the ordinary course of its business or furnished by such subscriber or user for connection to the facilities of such service and used in the ordinary course of its business; or (ii) being used by a provider of wire or electronic communication service in the ordinary course of its business, or by an investigative or law enforcement officer in the ordinary course of his duties;"],[2,"(b) a hearing aid or similar device being used to correct subnormal hearing to not better than normal;"],[1,"(6) \"person\" means any employee, or agent of the United States or any State or political subdivision thereof, and any individual, partnership, association, joint stock company, trust, or corporation;"],[1,"(7) \"Investigative or law enforcement officer\" means any officer of the United States or of a State or political subdivision thereof, who is empowered by law to conduct investigations of or to make arrests for offenses enumerated in this chapter, and any attorney authorized by law to prosecute or participate in the prosecution of such offenses;"],[1,"(8) \"contents\", when used with respect to any wire, oral, or electronic communication, includes any information concerning the substance, purport, or meaning of that communication;"],[1,"(9) \"Judge of competent jurisdiction\" means—"],[2,"(a) a judge of a United States district court or a United States court of appeals; and"],[2,"(b) a judge of any court of general criminal jurisdiction of a State who is authorized by a statute of that State to enter orders authorizing interceptions of wire, oral, or electronic communications;"],[1,"(10) \"communication common carrier\" has the meaning given that term in section 3 of the Communications Act of 1934;"],[1,"(11) \"aggrieved person\" means a person who was a party to any intercepted wire, oral, or electronic communication or a person against whom the interception was directed;"],[1,"(12) \"electronic communication\" means any transfer of signs, signals, writing, images, sounds, data, or intelligence of any nature transmitted in whole or in part by a wire, radio, electromagnetic, photoelectronic or photooptical system that affects interstate or foreign commerce, but does not include—"],[2,"(A) any wire or oral communication;"],[2,"(B) any communication made through a tone-only paging device;"],[2,"(C) any communication from a tracking device (as defined in section 3117 of this title); or"],[2,"(D) electronic funds transfer information stored by a financial institution in a communications system used for the electronic storage and transfer of funds;"],[1,"(13) \"user\" means any person or entity who—"],[2,"(A) uses an electronic communication service; and"],[2,"(B) is duly authorized by the provider of such service to engage in such use;"],[1,"(14) \"electronic communications system\" means any wire, radio, electromagnetic, photooptical or photoelectronic facilities for the transmission of wire or electronic communications, and any computer facilities or related electronic equipment for the electronic storage of such communications;"],[1,"(15) \"electronic communication service\" means any service which provides to users thereof the ability to send or receive wire or electronic communications;"],[1,"(16) \"readily accessible to the general public\" means, with respect to a radio communication, that such communication is not—"],[2,"(A) scrambled or encrypted;"],[2,"(B) transmitted using modulation techniques whose essential parameters have been withheld from the public with the intention of preserving the privacy of such communication;"],[2,"(C) carried on a subcarrier or other signal subsidiary to a radio transmission;"],[2,"(D) transmitted over a communication system provided by a common carrier, unless the communication is a tone only paging system communication; or"],[2,"(E) transmitted on frequencies allocated under part 25, subpart D, E, or F of part 74, or part 94 of the Rules of the Federal Communications Commission, unless, in the case of a communication transmitted on a frequency allocated under part 74 that is not exclusively allocated to broadcast auxiliary services, the communication is a two-way voice communication by radio;"],[1,"(17) \"electronic storage\" means—"],[2,"(A) any temporary, intermediate storage of a wire or electronic communication incidental to the electronic transmission thereof; and"],[2,"(B) any storage of such communication by an electronic communication service for purposes of backup protection of such communication;"],[1,"(18) \"aural transfer\" means a transfer containing the human voice at any point between and including the point of origin and the point of reception;"],[1,"(19) \"foreign intelligence information\", for purposes of section 2517(6) of this title, means—"],[2,"(A) information, whether or not concerning a United States person, that relates to the ability of the United States to protect against—"],[3,"(i) actual or potential attack or other grave hostile acts of a foreign power or an agent of a foreign power;"],[3,"(ii) sabotage or international terrorism by a foreign power or an agent of a foreign power; or"],[3,"(iii) clandestine intelligence activities by an intelligence service or network of a foreign power or by an agent of a foreign power; or"],[2,"(B) information, whether or not concerning a United States person, with respect to a foreign power or foreign territory that relates to—"],[3,"(i) the national defense or the security of the United States; or"],[3,"(ii) the conduct of the foreign affairs of the United States;"],[1,"(20) \"protected computer\" has the meaning set forth in section 1030; and"],[1,"(21) \"computer trespasser\"—"],[2,"(A) means a person who accesses a protected computer without authorization and thus has no reasonable expectation of privacy in any communication transmitted to, through, or from the protected computer; and"],[2,"(B) does not include a person known by the owner or operator of the protected computer to have an existing contractual relationship with the owner or operator of the protected computer for access to all or part of the protected computer."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2510?type=usc&year=mostrecent&link-type=html"},"by":{"0":"19","1":"29"}},{"t":"usc","label":"18 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/18/2701","subs":["(a)"],"stext":{"head":"§2701. Unlawful access to stored communications","paras":[[0,"(a) Offense.—Except as provided in subsection (c) of this section whoever—"],[1,"(1) intentionally accesses without authorization a facility through which an electronic communication service is provided; or"],[1,"(2) intentionally exceeds an authorization to access that facility;"],[0,"and thereby obtains, alters, or prevents authorized access to a wire or electronic communication while it is in electronic storage in such system shall be punished as provided in subsection (b) of this section."],[0,"(b) Punishment.—The punishment for an offense under subsection (a) of this section is—"],[1,"(1) if the offense is committed for purposes of commercial advantage, malicious destruction or damage, or private commercial gain, or in furtherance of any criminal or tortious act in violation of the Constitution or laws of the United States or any State—"],[2,"(A) a fine under this title or imprisonment for not more than 5 years, or both, in the case of a first offense under this subparagraph; and"],[2,"(B) a fine under this title or imprisonment for not more than 10 years, or both, for any subsequent offense under this subparagraph; and"],[1,"(2) in any other case—"],[2,"(A) a fine under this title or imprisonment for not more than 1 year or both, in the case of a first offense under this paragraph; and"],[2,"(B) a fine under this title or imprisonment for not more than 5 years, or both, in the case of an offense under this subparagraph that occurs after a conviction of another offense under this section."],[0,"(c) Exceptions.—Subsection (a) of this section does not apply with respect to conduct authorized—"],[1,"(1) by the person or entity providing a wire or electronic communications service;"],[1,"(2) by a user of that service with respect to a communication of or intended for that user; or"],[1,"(3) in section 2703, 2704 or 2518 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2701?type=usc&year=mostrecent&link-type=html"},"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"access to a wire or electronic communication while it is in electronic storage,","cite":"18 U.S.C. §§ 2701(a), 2707"}]},{"t":"usc","label":"18 U.S.C. § 2703","url":"https://www.law.cornell.edu/uscode/text/18/2703","subs":["(a)","(b)(1)(A)","(d)"],"stext":{"head":"§2703. Required disclosure of customer communications or records","paras":[[0,"(a) Contents of Wire or Electronic Communications in Electronic Storage.—A governmental entity may require the disclosure by a provider of electronic communication service of the contents of a wire or electronic communication, that is in electronic storage in an electronic communications system for one hundred and eighty days or less, only pursuant to a warrant issued using the procedures described in the Federal Rules of Criminal Procedure (or, in the case of a State court, issued using State warrant procedures and, in the case of a court-martial or other proceeding under chapter 47 of title 10 (the Uniform Code of Military Justice), issued under section 846 of that title, in accordance with regulations prescribed by the President) by a court of competent jurisdiction. A governmental entity may require the disclosure by a provider of electronic communications services of the contents of a wire or electronic communication that has been in electronic storage in an electronic communications system for more than one hundred and eighty days by the means available under subsection (b) of this section."],[0,"(b) Contents of Wire or Electronic Communications in a Remote Computing Service.—(1) A governmental entity may require a provider of remote computing service to disclose the contents of any wire or electronic communication to which this paragraph is made applicable by paragraph (2) of this subsection—"],[1,"(A) without required notice to the subscriber or customer, if the governmental entity obtains a warrant issued using the procedures described in the Federal Rules of Criminal Procedure (or, in the case of a State court, issued using State warrant procedures and, in the case of a court-martial or other proceeding under chapter 47 of title 10 (the Uniform Code of Military Justice), issued under section 846 of that title, in accordance with regulations prescribed by the President) by a court of competent jurisdiction; or"],[1,"(B) with prior notice from the governmental entity to the subscriber or customer if the governmental entity—"],[2,"(i) uses an administrative subpoena authorized by a Federal or State statute or a Federal or State grand jury or trial subpoena; or"],[2,"(ii) obtains a court order for such disclosure under subsection (d) of this section;"],[1,"except that delayed notice may be given pursuant to section 2705 of this title."],[0,"(2) Paragraph (1) is applicable with respect to any wire or electronic communication that is held or maintained on that service—"],[1,"(A) on behalf of, and received by means of electronic transmission from (or created by means of computer processing of communications received by means of electronic transmission from), a subscriber or customer of such remote computing service; and"],[1,"(B) solely for the purpose of providing storage or computer processing services to such subscriber or customer, if the provider is not authorized to access the contents of any such communications for purposes of providing any services other than storage or computer processing."],[0,"(c) Records Concerning Electronic Communication Service or Remote Computing Service.—(1) A governmental entity may require a provider of electronic communication service or remote computing service to disclose a record or other information pertaining to a subscriber to or customer of such service (not including the contents of communications) only when the governmental entity—"],[1,"(A) obtains a warrant issued using the procedures described in the Federal Rules of Criminal Procedure (or, in the case of a State court, issued using State warrant procedures and, in the case of a court-martial or other proceeding under chapter 47 of title 10 (the Uniform Code of Military Justice), issued under section 846 of that title, in accordance with regulations prescribed by the President) by a court of competent jurisdiction;"],[1,"(B) obtains a court order for such disclosure under subsection (d) of this section;"],[1,"(C) has the consent of the subscriber or customer to such disclosure;"],[1,"(D) submits a formal written request relevant to a law enforcement investigation concerning telemarketing fraud for the name, address, and place of business of a subscriber or customer of such provider, which subscriber or customer is engaged in telemarketing (as such term is defined in section 2325 of this title); or"],[1,"(E) seeks information under paragraph (2)."],[0,"(2) A provider of electronic communication service or remote computing service shall disclose to a governmental entity the—"],[1,"(A) name;"],[1,"(B) address;"],[1,"(C) local and long distance telephone connection records, or records of session times and durations;"],[1,"(D) length of service (including start date) and types of service utilized;"],[1,"(E) telephone or instrument number or other subscriber number or identity, including any temporarily assigned network address; and"],[1,"(F) means and source of payment for such service (including any credit card or bank account number),"],[0,"of a subscriber to or customer of such service when the governmental entity uses an administrative subpoena authorized by a Federal or State statute or a Federal or State grand jury or trial subpoena or any means available under paragraph (1)."],[0,"(3) A governmental entity receiving records or information under this subsection is not required to provide notice to a subscriber or customer."],[0,"(d) Requirements for Court Order.—A court order for disclosure under subsection (b) or (c) may be issued by any court that is a court of competent jurisdiction and shall issue only if the governmental entity offers specific and articulable facts showing that there are reasonable grounds to believe that the contents of a wire or electronic communication, or the records or other information sought, are relevant and material to an ongoing criminal investigation. In the case of a State governmental authority, such a court order shall not issue if prohibited by the law of such State. A court issuing an order pursuant to this section, on a motion made promptly by the service provider, may quash or modify such order, if the information or records requested are unusually voluminous in nature or compliance with such order otherwise would cause an undue burden on such provider."],[0,"(e) No Cause of Action Against a Provider Disclosing Information Under This Chapter.—No cause of action shall lie in any court against any provider of wire or electronic communication service, its officers, employees, agents, or other specified persons for providing information, facilities, or assistance in accordance with the terms of a court order, warrant, subpoena, statutory authorization, or certification under this chapter."],[0,"(f) Requirement To Preserve Evidence.—"],[1,"(1) In general.—A provider of wire or electronic communication services or a remote computing service, upon the request of a governmental entity, shall take all necessary steps to preserve records and other evidence in its possession pending the issuance of a court order or other process."],[1,"(2) Period of retention.—Records referred to in paragraph (1) shall be retained for a period of 90 days, which shall be extended for an additional 90-day period upon a renewed request by the governmental entity."],[0,"(g) Presence of Officer Not Required.—Notwithstanding section 3105 of this title, the presence of an officer shall not be required for service or execution of a search warrant issued in accordance with this chapter requiring disclosure by a provider of electronic communications service or remote computing service of the contents of communications or records or other information pertaining to a subscriber to or customer of such service."],[0,"(h) Comity Analysis and Disclosure of Information Regarding Legal Process Seeking Contents of Wire or Electronic Communication.—"],[1,"(1) Definitions.—In this subsection—"],[2,"(A) the term \"qualifying foreign government\" means a foreign government—"],[3,"(i) with which the United States has an executive agreement that has entered into force under section 2523; and"],[3,"(ii) the laws of which provide to electronic communication service providers and remote computing service providers substantive and procedural opportunities similar to those provided under paragraphs (2) and (5); and"],[2,"(B) the term \"United States person\" has the meaning given the term in section 2523."],[1,"(2) Motions to quash or modify.—(A) A provider of electronic communication service to the public or remote computing service, including a foreign electronic communication service or remote computing service, that is being required to disclose pursuant to legal process issued under this section the contents of a wire or electronic communication of a subscriber or customer, may file a motion to modify or quash the legal process where the provider reasonably believes—"],[2,"(i) that the customer or subscriber is not a United States person and does not reside in the United States; and"],[2,"(ii) that the required disclosure would create a material risk that the provider would violate the laws of a qualifying foreign government."],[2,"Such a motion shall be filed not later than 14 days after the date on which the provider was served with the legal process, absent agreement with the government or permission from the court to extend the deadline based on an application made within the 14 days. The right to move to quash is without prejudice to any other grounds to move to quash or defenses thereto, but it shall be the sole basis for moving to quash on the grounds of a conflict of law related to a qualifying foreign government."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2703?type=usc&year=mostrecent&link-type=html"},"by":{"0":"19, 19, 40","1":"28","2":"10"},"q":[{"src":"brief","b":0,"text":"contents of a wire or electronic communication that is in electronic storage.","cite":"18 U.S.C. § 2703(a)"},{"src":"brief","b":0,"text":"relevant and material to an ongoing criminal investigation.","cite":"18 U.S.C. § 2703(d)"},{"src":"brief","b":1,"text":"the contents of a wire or electronic communication, that is in electronic storage in an electronic communications system for one hundred and eighty days or less.","cite":"18 U.S.C. 2703(a)"}]},{"t":"usc","label":"18 U.S.C. § 2707","url":"https://www.law.cornell.edu/uscode/text/18/2707","by":{"0":"19"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"47 U.S.C. § 222","url":"https://www.law.cornell.edu/uscode/text/47/222","subs":["(c)","(h)(1)(A)"],"by":{"0":"24, 24"}},{"t":"case","label":"Andresen v. Maryland","cite":"427 U.S. 463","y":1976,"id":"1975/74-1646","sc":1,"by":{"1":"38, 45, 46"},"q":[{"src":"brief","b":1,"text":"the seizure of one thing under a warrant describing another.","cite":"427 U.S. 463, 480"},{"src":"brief","b":1,"text":"it is certain that some innocuous documents will be examined, at least cursorily, in order to determine whether they are, in fact, among those papers authorized to be seized.","cite":"427 U.S. at 482 n.11"}]},{"t":"case","label":"Byrd v. United States","cite":"138 S. Ct. 1518","y":2018,"id":"2017/16-1371","sc":1,"by":{"1":"30"},"q":[{"src":"argument","who":"Mr. Unikowsky","text":"If there was a flashing warning saying that, you know, we reserve the right to give for any -- any reason whatsoever, I think that might be more pertinent to the property theory than the privacy theory because, on the privacy theory, you know, the Court said in the Byrd case that, you know, terms of use aren't necessarily dispositive."}]},{"t":"case","label":"25, 31, 32, 36, 37, 41-43, 45 City of Los Angeles v. Patel","cite":"576 U.S. 409","y":2015,"id":"2014/13-1175","sc":1,"by":{"1":"45"}},{"t":"case","label":"Couch v. United States","cite":"409 U.S. 322","y":1973,"id":"1972/71-889","sc":1,"by":{"1":"28"}},{"t":"case","label":"Feist Pubs., Inc. v. Rural Tel. Serv. Co.","cite":"499 U.S. 340","y":1991,"id":"1990/89-1909","sc":1,"by":{"1":"32"}},{"t":"case","label":"Florida v. Jardines","cite":"569 U.S. 1","y":2013,"id":"2012/11-564","sc":1,"by":{"1":"31","2":"2, 14"}},{"t":"case","label":"Hester v. United States","cite":"265 U.S. 57","y":1924,"id":"scdb/1923-131","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"the special protection accorded by the Fourth Amendment to the people in their ‘persons, houses, papers, and effects’ is not extended to the open fields","cite":"265 U.S. 57, 59"}]},{"t":"case","label":"Hoffa v. United States","cite":"385 U.S. 293","y":1966,"id":"1966/32","sc":1,"by":{"1":"16, 28, 32"},"q":[{"src":"brief","b":1,"text":"that the Fourth Amendment protects a wrongdoer’s misplaced belief that a person to whom he voluntarily confides his wrongdoing will not reveal it.","cite":"385 U.S. 293, 302"}]},{"t":"case","label":"Illinois v. Lidster","cite":"540 U.S. 419","y":2004,"id":"2003/02-1060","sc":1,"by":{"1":"45"}},{"t":"case","label":"Lopez v. United States","cite":"373 U.S. 427","y":1963,"id":"1962/236","sc":1,"by":{"1":"15"}},{"t":"case","label":"Massachusetts v. Upton","cite":"466 U.S. 727","y":1984,"id":"1983/83-1338","sc":1,"by":{"1":"40"}},{"t":"case","label":"Messerschmidt v. Millender","cite":"565 U.S. 535","y":2012,"id":"2011/10-704","sc":1,"by":{"1":"38, 39"},"q":[{"src":"brief","b":1,"text":"will aid in a particular apprehension or conviction,","cite":"565 U.S. 535, 552 n.7"}]},{"t":"case","label":"Minnesota v. Carter","cite":"525 U.S. 83","y":1998,"id":"1998/97-1147","sc":1,"by":{"1":"34"}},{"t":"case","label":"Oklahoma Press Publ’g Co. v. Walling","cite":"327 U.S. 186","y":1946,"id":"scdb/1945-112","sc":1,"by":{"1":"41"},"q":[{"src":"argument","who":"Mr. Feigin","text":"Well, not only do I think that, Your Honor, but I think the Court has said that multiple times if you look at cases like Oklahoma Press against Walling or Lone Steer."}]},{"t":"case","label":"Oliver v. United States","cite":"466 U.S. 170","y":1984,"id":"1983/82-15","sc":1,"by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"term ‘effects’ is less inclusive than ‘property,’","cite":"466 U.S. 170, 176"}]},{"t":"case","label":"Rakas v. Illinois","cite":"439 U.S. 128","y":1978,"id":"1978/77-5781","sc":1,"by":{"1":"44"}},{"t":"case","label":"Rawlings v. Kentucky","cite":"448 U.S. 98","y":1980,"id":"1979/79-5146","sc":1,"by":{"1":"29"}},{"t":"case","label":"Scott v. United States","cite":"436 U.S. 128","y":1978,"id":"1977/76-6767","sc":1,"by":{"1":"47"}},{"t":"case","label":"Soldal v. Cook Cnty.","cite":"506 U.S. 56","y":1992,"id":"1992/91-6516","sc":1,"by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"does not protect possessory interests in all kinds of property.","cite":"506 U.S. 56, 62 n.7"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"protect[s] certain expectations of privacy as well.","cite":"506 U. S. 56, 64"}]},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"by":{"1":"15-17, 20, 31","2":"2, 8"},"q":[{"src":"brief","b":1,"text":"when government officers violate a person’s ‘reasonable expectation of privacy.’","cite":"565 U.S. 400, 406-407"},{"src":"brief","b":2,"text":"assur[es] preservation of that degree of privacy against government that existed when the Fourth Amendment was adopted.","cite":"565 U.S. 400, 406"}]},{"t":"case","label":"United States v. Karo","cite":"468 U.S. 705","y":1984,"id":"1983/83-850","sc":1,"by":{"1":"24, 44","2":"10"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"Why isn't this closer to the warrants that we permitted with beepers, where we don't have a person or necessarily a place in mind, but we have a location and general things, why isn't that more consonant with Berger, Zucker, Karo, those lines of cases?"},{"src":"argument","who":"Mr. Feigin","text":"Number two, I think this would make this case somewhat like Karo, where it doesn't invalidate the law enforcement technique ab initio. It just means that someone with standing could suppress the information about the particular home."},{"src":"argument","who":"Mr. Feigin","text":"Your Honor, I think -- I think what I'm saying is two things. One, I do think we could have done that here because of the warrant, like under Karo."}]},{"t":"case","label":"United States v. Knotts","cite":"460 U.S. 276","y":1983,"id":"1982/81-1802","sc":1,"by":{"1":"2, 12, 13, 17-20, 24","2":"10"},"q":[{"src":"brief","b":1,"text":"scientific enhancement of this sort raises no constitutional issues which visual surveillance would not also raise.","cite":"460 U.S. at 285"},{"src":"argument","who":"Mr. Unikowsky","text":"It's -- I think it's quite different from a case like Knotts, where, you know, the police were following someone on a highway and they put a beeper just to enhance the quality of the visual surveillance."},{"src":"argument","who":"Mr. Feigin","text":"I question whether that is a -- an invasion of their reasonable privacy expectations. I think clearly not under this Court's decision in Knotts. That's a public place. These were public movements."},{"src":"argument","who":"Mr. Feigin","text":"And this Court has made clear that it's different. So, in Knotts, the Court makes clear that --"}]},{"t":"case","label":"United States v. Leon","cite":"468 U.S. 897","y":1984,"id":"1983/82-1771","sc":1,"by":{"1":"48"},"q":[{"src":"brief","b":1,"text":"an issue separate from the question whether the Fourth Amendment rights of the party seeking to invoke the rule were violated.","cite":"468 U.S. 897, 906"},{"src":"opinion","who":"Opinion of the Court (Justice Kagan)","text":"to guide future action by law enforcement offcers and magistrates.","cite":"468 U. S. 897, 925"},{"src":"argument","who":"Mr. Unikowsky","text":"We'd say that the Leon good-faith exception applies to fact-bound challenges to probable cause determinations in a particular case and shouldn't apply where we're challenging a new and fundamentally different type of warrant."},{"src":"argument","who":"Mr. Unikowsky","text":"I think that the -- that the premise of Leon is that it's not necessary to apply the exclusionary rule in the case of a fact-bound challenge to a probable cause determination in a particular case because probable cause is litigated all the time outside the context of warrants, whereas, in an issue like this, a challenge to a fundamental new type of warrant, I do think litigants need an adequate incentive to litigate the constitutionality of such warrants, and the only way that'll happen is through the exclusionary rule."}]},{"t":"case","label":"United States v. Ruiz","cite":"536 U.S. 622","y":2002,"id":"2001/01-595","sc":1,"by":{"1":"26"}},{"t":"case","label":"Zurcher v. Stanford Daily","cite":"436 U.S. 547","y":1978,"id":"1977/76-1484","sc":1,"by":{"1":"3, 13, 38, 45","2":"16, 17"},"q":[{"src":"brief","b":1,"text":"reasonable cause to believe that the specific ‘things’ to be searched for and seized are located","cite":"436 U.S. at 556"},{"src":"argument","who":"Justice Kavanaugh","text":"Assuming it's a search for purposes of this question and that I don't buy your general warrant argument, how can you overcome Zurcher for purposes of your argument that it's not sufficiently particularized, et cetera?"},{"src":"argument","who":"Mr. Unikowsky","text":"So I view Zurcher as answering a very different question from this case. So Zurcher holds that the Fourth Amendment permits a search of a premises of someone who is not implicated in the crime at all as long as there's probable cause to believe that there's evidence on those premises that will be pertinent to the criminal investigation --"},{"src":"argument","who":"Mr. Unikowsky","text":"-- to have happened here is more like a search of, you know, 19 separate safety deposit boxes rather than one single place, the Stanford University office, like in Zurcher."}]},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"43"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)(1)(A)(i)","(c)(1)(A)(ii)"],"by":{"1":"4, 4"}},{"t":"usc","label":"18 U.S.C. § 2113","url":"https://www.law.cornell.edu/uscode/text/18/2113","subs":["(a)","(d)"],"by":{"1":"4, 4"}},{"t":"usc","label":"18 U.S.C. § 2518","url":"https://www.law.cornell.edu/uscode/text/18/2518","subs":["(5)"],"stext":{"head":"§2518. Procedure for interception of wire, oral, or electronic communications","paras":[[0,"(1) Each application for an order authorizing or approving the interception of a wire, oral, or electronic communication under this chapter shall be made in writing upon oath or affirmation to a judge of competent jurisdiction and shall state the applicant's authority to make such application. Each application shall include the following information:"],[1,"(a) the identity of the investigative or law enforcement officer making the application, and the officer authorizing the application;"],[1,"(b) a full and complete statement of the facts and circumstances relied upon by the applicant, to justify his belief that an order should be issued, including (i) details as to the particular offense that has been, is being, or is about to be committed, (ii) except as provided in subsection (11), a particular description of the nature and location of the facilities from which or the place where the communication is to be intercepted, (iii) a particular description of the type of communications sought to be intercepted, (iv) the identity of the person, if known, committing the offense and whose communications are to be intercepted;"],[1,"(c) a full and complete statement as to whether or not other investigative procedures have been tried and failed or why they reasonably appear to be unlikely to succeed if tried or to be too dangerous;"],[1,"(d) a statement of the period of time for which the interception is required to be maintained. If the nature of the investigation is such that the authorization for interception should not automatically terminate when the described type of communication has been first obtained, a particular description of facts establishing probable cause to believe that additional communications of the same type will occur thereafter;"],[1,"(e) a full and complete statement of the facts concerning all previous applications known to the individual authorizing and making the application, made to any judge for authorization to intercept, or for approval of interceptions of, wire, oral, or electronic communications involving any of the same persons, facilities or places specified in the application, and the action taken by the judge on each such application; and"],[1,"(f) where the application is for the extension of an order, a statement setting forth the results thus far obtained from the interception, or a reasonable explanation of the failure to obtain such results."],[0,"(2) The judge may require the applicant to furnish additional testimony or documentary evidence in support of the application."],[0,"(3) Upon such application the judge may enter an ex parte order, as requested or as modified, authorizing or approving interception of wire, oral, or electronic communications within the territorial jurisdiction of the court in which the judge is sitting (and outside that jurisdiction but within the United States in the case of a mobile interception device authorized by a Federal court within such jurisdiction), if the judge determines on the basis of the facts submitted by the applicant that—"],[1,"(a) there is probable cause for belief that an individual is committing, has committed, or is about to commit a particular offense enumerated in section 2516 of this chapter;"],[1,"(b) there is probable cause for belief that particular communications concerning that offense will be obtained through such interception;"],[1,"(c) normal investigative procedures have been tried and have failed or reasonably appear to be unlikely to succeed if tried or to be too dangerous;"],[1,"(d) except as provided in subsection (11), there is probable cause for belief that the facilities from which, or the place where, the wire, oral, or electronic communications are to be intercepted are being used, or are about to be used, in connection with the commission of such offense, or are leased to, listed in the name of, or commonly used by such person."],[0,"(4) Each order authorizing or approving the interception of any wire, oral, or electronic communication under this chapter shall specify—"],[1,"(a) the identity of the person, if known, whose communications are to be intercepted;"],[1,"(b) the nature and location of the communications facilities as to which, or the place where, authority to intercept is granted;"],[1,"(c) a particular description of the type of communication sought to be intercepted, and a statement of the particular offense to which it relates;"],[1,"(d) the identity of the agency authorized to intercept the communications, and of the person authorizing the application; and"],[1,"(e) the period of time during which such interception is authorized, including a statement as to whether or not the interception shall automatically terminate when the described communication has been first obtained."],[0,"An order authorizing the interception of a wire, oral, or electronic communication under this chapter shall, upon request of the applicant, direct that a provider of wire or electronic communication service, landlord, custodian or other person shall furnish the applicant forthwith all information, facilities, and technical assistance necessary to accomplish the interception unobtrusively and with a minimum of interference with the services that such service provider, landlord, custodian, or person is according the person whose communications are to be intercepted. Any provider of wire or electronic communication service, landlord, custodian or other person furnishing such facilities or technical assistance shall be compensated therefor by the applicant for reasonable expenses incurred in providing such facilities or assistance. Pursuant to section 2522 of this chapter, an order may also be issued to enforce the assistance capability and capacity requirements under the Communications Assistance for Law Enforcement Act."],[0,"(5) No order entered under this section may authorize or approve the interception of any wire, oral, or electronic communication for any period longer than is necessary to achieve the objective of the authorization, nor in any event longer than thirty days. Such thirty-day period begins on the earlier of the day on which the investigative or law enforcement officer first begins to conduct an interception under the order or ten days after the order is entered. Extensions of an order may be granted, but only upon application for an extension made in accordance with subsection (1) of this section and the court making the findings required by subsection (3) of this section. The period of extension shall be no longer than the authorizing judge deems necessary to achieve the purposes for which it was granted and in no event for longer than thirty days. Every order and extension thereof shall contain a provision that the authorization to intercept shall be executed as soon as practicable, shall be conducted in such a way as to minimize the interception of communications not otherwise subject to interception under this chapter, and must terminate upon attainment of the authorized objective, or in any event in thirty days. In the event the intercepted communication is in a code or foreign language, and an expert in that foreign language or code is not reasonably available during the interception period, minimization may be accomplished as soon as practicable after such interception. An interception under this chapter may be conducted in whole or in part by Government personnel, or by an individual operating under a contract with the Government, acting under the supervision of an investigative or law enforcement officer authorized to conduct the interception."],[0,"(6) Whenever an order authorizing interception is entered pursuant to this chapter, the order may require reports to be made to the judge who issued the order showing what progress has been made toward achievement of the authorized objective and the need for continued interception. Such reports shall be made at such intervals as the judge may require."],[0,"(7) Notwithstanding any other provision of this chapter, any investigative or law enforcement officer, specially designated by the Attorney General, the Deputy Attorney General, the Associate Attorney General, or by the principal prosecuting attorney of any State or subdivision thereof acting pursuant to a statute of that State, who reasonably determines that—"],[1,"(a) an emergency situation exists that involves—"],[2,"(i) immediate danger of death or serious physical injury to any person,"],[2,"(ii) conspiratorial activities threatening the national security interest, or"],[2,"(iii) conspiratorial activities characteristic of organized crime,"],[1,"that requires a wire, oral, or electronic communication to be intercepted before an order authorizing such interception can, with due diligence, be obtained, and"],[1,"(b) there are grounds upon which an order could be entered under this chapter to authorize such interception,"],[0,"may intercept such wire, oral, or electronic communication if an application for an order approving the interception is made in accordance with this section within forty-eight hours after the interception has occurred, or begins to occur. In the absence of an order, such interception shall immediately terminate when the communication sought is obtained or when the application for the order is denied, whichever is earlier. In the event such application for approval is denied, or in any other case where the interception is terminated without an order having been issued, the contents of any wire, oral, or electronic communication intercepted shall be treated as having been obtained in violation of this chapter, and an inventory shall be served as provided for in subsection (d) of this section on the person named in the application."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2518?type=usc&year=mostrecent&link-type=html"},"by":{"1":"46"},"q":[{"src":"brief","b":1,"text":"conducted in such a way as to minimize the interception of communications not otherwise subject to interception under this chapter.","cite":"18 U.S.C. 2518(5)"}]},{"t":"usc","label":"18 U.S.C. § 3117","url":"https://www.law.cornell.edu/uscode/text/18/3117","subs":["(b)"],"by":{"1":"29"}},{"t":"case","label":"Calhoun v. Google LLC","cite":"526 F. Supp. 3d 605","y":2021,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/526/605/","by":{"2":"4"}},{"t":"case","label":"Case v. Montana","cite":"146 S. Ct. 500","y":2026,"id":"2025/24-624","sc":1,"by":{"2":"12"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"We will hear argument first this morning in Case 25-112, Chatrie versus United States. Mr. Unikowsky. ORAL ARGUMENT OF ADAM G. UNIKOWSKY ON BEHALF OF THE PETITIONER"},{"src":"argument","who":"Mr. Feigin","text":"Chief Justice, I don't know how he concedes exigent circumstances because, under this Court's recent decision just this term in Case against Montana, we need reasonable cause to believe that the -- there's a necessary search, and under his view, the -- this would be a search of everyone who has location history stored with Google."}]},{"t":"case","label":"Rodriguez v. ByteDance, Inc.","cite":"2025 WL 672951","y":2025,"court":"N.D. Ill. Mar. 3","by":{"2":"4"}},{"t":"case","label":"Tyler v. Hennepin County","cite":"598 U.S. 631","y":2023,"id":"2022/22-166","sc":1,"by":{"2":"3"},"q":[{"src":"argument","who":"Mr. Unikowsky","text":"Like the Court held in the Tyler versus Hennepin case, you know, the Court should consider a common law rule, not -- not state by state. But I think state law is a pertinent input into the ultimate federal question, and the fact that Virginia and many other states have explicitly recognized data as a type of property and have created statutory torts for trespass on that data is, I think, pertinent to the Fourth Amendment question here."}]},{"t":"case","label":"Van Buren v. United States","cite":"593 U.S. 374","y":2021,"id":"2020/19-783","sc":1,"by":{"2":"5-6"},"q":[{"src":"brief","b":2,"text":"[b]y now, it is well established that information contained in a computer is ‘property’…. Federal and state law routinely define ‘property’ to include computer data.","cite":"593 U.S. 374, 400"}]}]};